    """
    Implements the Bellman-Ford algorithm to find the shortest path in a weighted directed graph
    represented as an adjacency list. It can handle graphs with negative weight edges.
    """
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    predecessor = {node: None for node in graph}

    for _ in range(len(graph) - 1):
        for node in graph:
            for neighbor, weight in graph[node]:
                if distances[node] + weight < distances[neighbor]:
                    distances[neighbor] = distances[node] + weight
                    predecessor[neighbor] = node

    for node in graph:
        for neighbor, weight in graph[node]:
            if distances[node] + weight < distances[neighbor]:
                return (float('inf'), [])  # Negative cycle detected

    path = []
    current = end
    while current is not None:
        path.append(current)
        current = predecessor[current]

    path.reverse()

    if distances[end] == float('inf'):
        return (float('inf'), [])

    return (distances[end], path)

